/// 解析 wait 指令
///
/// 语法: `wait <duration>`，duration 为秒数（正数）
pub(super) fn parse_wait(
    &self,
    line: &str,
    line_number: usize,
) -> Result<Option<ScriptNode>, ParseError> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 2 {
        return Err(ParseError::MissingParameter {
            line: line_number,
            command: "wait".to_string(),
            param: "等待时长（秒）".to_string(),
        });
    }

    let duration: f64 = parts[1].parse().map_err(|_| ParseError::InvalidParameter {
        line: line_number,
        param: "duration".to_string(),
        message: format!("无法解析为数字: '{}'", parts[1]),
    })?;

    if duration <= 0.0 {
        return Err(ParseError::InvalidParameter {
            line: line_number,
            param: "duration".to_string(),
            message: format!("等待时长必须为正数，实际: {duration}"),
        });
    }

    Ok(Some(ScriptNode::Wait { duration }))
}

/// 解析表格块（选择分支）

ScriptNode::ClearCharacters => {
    // 清除状态中的所有角色
    state.visible_characters.clear();
    Ok(ExecuteResult::with_commands(vec![Command::ClearCharacters]))
}

ScriptNode::Wait { duration } => Ok(ExecuteResult::with_wait(
    vec![],
    WaitingReason::WaitForTime(std::time::Duration::from_secs_f64(*duration)),
)),

ScriptNode::Pause => Ok(ExecuteResult::with_wait(
    vec![],
    WaitingReason::WaitForClick,
)),

