    r#"
    document.addEventListener("keydown", function(e) {
        dioxus.send({ type: "down", key: e.key, code: e.code });
    });
    "#,
);
loop {
    let msg: Result<serde_json::Value, _> = eval.recv().await;
    // ...
}
```

注意 eval 是 **async** 的，必须在 `spawn(async move { ... })` 中调用。

