    spawn(async move {
        let mut eval = document::eval(
            r#"
            // 在 WebView 中创建 CodeMirror 实例
            const editor = new CodeMirror.EditorView({
                parent: document.getElementById("editor-container"),
                // ...
            });
            // 保持 eval 存活，用于后续通信
